INSERT INTO exercises (id, lesson_id, title, instruction, audio_url, content, exercise_type, skill_type, time_limit, max_attempts, passing_score, ordering)
VALUES
    ('60000000-0000-0000-0000-000000000001', NULL, 'Grammar Drill - Articles (a / an / the)', 'Choose the correct article or write the missing article (a, an or the).', NULL, NULL, 'PRACTICE', 'READING', 600, 99, 0, 101),
    ('60000000-0000-0000-0000-000000000002', NULL, 'Grammar Drill - Verb Tenses', 'Choose the correct verb form or write the missing verb form.', NULL, NULL, 'PRACTICE', 'READING', 600, 99, 0, 102),
    ('60000000-0000-0000-0000-000000000003', NULL, 'Grammar Drill - Subject-Verb Agreement and Noun Number', 'Choose the correct word or write the missing word.', NULL, NULL, 'PRACTICE', 'READING', 600, 99, 0, 103),
    ('60000000-0000-0000-0000-000000000004', NULL, 'Grammar Drill - Prepositions', 'Choose the correct preposition or write the missing preposition.', NULL, NULL, 'PRACTICE', 'READING', 600, 99, 0, 104),
    ('60000000-0000-0000-0000-000000000005', NULL, 'Grammar Drill - Complex Sentences', 'Choose the correct sentence or write the missing word.', NULL, NULL, 'PRACTICE', 'READING', 600, 99, 0, 105),
    ('60000000-0000-0000-0000-000000000006', NULL, 'Grammar Drill - Punctuation', 'Choose the sentence or the punctuation mark that is correct.', NULL, NULL, 'PRACTICE', 'READING', 600, 99, 0, 106),
    ('60000000-0000-0000-0000-000000000007', NULL, 'Vocabulary Drill - Word Choice', 'Choose the best word or write the missing word.', NULL, NULL, 'PRACTICE', 'READING', 600, 99, 0, 107),
    ('60000000-0000-0000-0000-000000000008', NULL, 'Vocabulary Drill - Collocations', 'Choose the correct word or write the missing word.', NULL, NULL, 'PRACTICE', 'READING', 600, 99, 0, 108),
    ('60000000-0000-0000-0000-000000000009', NULL, 'Vocabulary Drill - Paraphrasing and Avoiding Repetition', 'Choose the best paraphrase or write the missing word.', NULL, NULL, 'PRACTICE', 'READING', 600, 99, 0, 109),
    ('60000000-0000-0000-0000-000000000010', NULL, 'Vocabulary Drill - Spelling and Word Forms', 'Choose the correct spelling or write the correct form of the word.', NULL, NULL, 'PRACTICE', 'READING', 600, 99, 0, 110),
    ('60000000-0000-0000-0000-000000000011', NULL, 'Writing Drill - Linking Words', 'Choose the best linking word or phrase.', NULL, NULL, 'PRACTICE', 'READING', 600, 99, 0, 111),
    ('60000000-0000-0000-0000-000000000012', NULL, 'Writing Task 1 Drill - Overview', 'Read the line graph description, then answer the questions.', NULL, '{"passageTitle": "Line graph: students on two types of course (thousands)", "paragraphs": [{"text": "The line graph shows the number of students (in thousands) on online courses and on classroom courses at a college between 2000 and 2020. Online courses: 2000 - 2; 2010 - 8; 2020 - 20. Classroom courses: 2000 - 15; 2010 - 14; 2020 - 9."}]}'::jsonb, 'PRACTICE', 'READING', 600, 99, 0, 112),
    ('60000000-0000-0000-0000-000000000013', NULL, 'Writing Task 1 Drill - Key Features', 'Read the bar chart description, then answer the questions.', NULL, '{"passageTitle": "Bar chart: households with internet access (%)", "paragraphs": [{"text": "The bar chart shows the percentage of households with internet access in four regions in 2005 and 2015. Region A: 20% in 2005, 60% in 2015. Region B: 35%, 70%. Region C: 10%, 30%. Region D: 50%, 85%."}]}'::jsonb, 'PRACTICE', 'READING', 600, 99, 0, 113),
    ('60000000-0000-0000-0000-000000000014', NULL, 'Writing Task 1 Drill - Comparing Data Accurately', 'Read the table description, then answer the questions.', NULL, '{"passageTitle": "Table: monthly spending of young people (US$)", "paragraphs": [{"text": "The table shows average monthly spending (US dollars) by young people on three items. Food: 200 in 2000, 250 in 2020. Transport: 80 in 2000, 120 in 2020. Entertainment: 60 in 2000, 150 in 2020."}]}'::jsonb, 'PRACTICE', 'READING', 600, 99, 0, 114),
    ('60000000-0000-0000-0000-000000000015', NULL, 'Writing Task 2 Drill - Stating Your Position', 'Topic: Some people think university education should be free. To what extent do you agree?', NULL, NULL, 'PRACTICE', 'READING', 600, 99, 0, 115),
    ('60000000-0000-0000-0000-000000000016', NULL, 'Writing Task 2 Drill - Answering All Parts of the Question', 'Topic: Why do some people choose to live abroad? Is this a positive or negative development?', NULL, NULL, 'PRACTICE', 'READING', 600, 99, 0, 116),
    ('60000000-0000-0000-0000-000000000017', NULL, 'Writing Task 2 Drill - Developing Ideas', 'Choose the best answer or write the missing word.', NULL, NULL, 'PRACTICE', 'READING', 600, 99, 0, 117),
    ('60000000-0000-0000-0000-000000000018', NULL, 'Writing Drill - Paragraphing', 'Choose the best answer or write the missing word.', NULL, NULL, 'PRACTICE', 'READING', 600, 99, 0, 118),
    ('60000000-0000-0000-0000-000000000019', NULL, 'Writing Drill - Referencing', 'Choose the best answer or write the missing word.', NULL, NULL, 'PRACTICE', 'READING', 600, 99, 0, 119),
    ('60000000-0000-0000-0000-000000000020', NULL, 'Speaking Drill - Extending Your Answer (Part 2)', 'Choose the best answer or write the missing word.', NULL, NULL, 'PRACTICE', 'READING', 600, 99, 0, 120),
    ('60000000-0000-0000-0000-000000000021', NULL, 'Speaking Drill - Discourse Markers', 'Choose the best answer or write the missing word.', NULL, NULL, 'PRACTICE', 'READING', 600, 99, 0, 121);
