INSERT INTO questions (id, exercise_id, question_group_id, question_text, question_type, image_url, audio_url, reading_passage, explanation, points, ordering)
VALUES
    ('0b961c5b-189c-5ce9-8b5a-4215933fe845', '60000000-0000-0000-0000-000000000001', '3f836684-d443-5e83-a2c7-657f1b80521c', 'In many countries, ______ education is free for children.', 'MULTIPLE_CHOICE', NULL, NULL, NULL, 'Danh từ không đếm được nói chung thì không dùng mạo từ.', 1, 1),
    ('e92e5ddd-0f67-5207-b881-3d42b8a149c3', '60000000-0000-0000-0000-000000000001', '3f836684-d443-5e83-a2c7-657f1b80521c', 'I visited ______ University of Melbourne last year.', 'MULTIPLE_CHOICE', NULL, NULL, NULL, 'Tên riêng dạng "University of + địa danh" dùng "the".', 1, 2),
    ('18ae88e8-3d87-585e-a50f-9f4affc7c44b', '60000000-0000-0000-0000-000000000001', '3f836684-d443-5e83-a2c7-657f1b80521c', 'She has ______ very good chance of passing the exam.', 'MULTIPLE_CHOICE', NULL, NULL, NULL, '"a chance" là danh từ đếm được số ít, chưa xác định.', 1, 3),
    ('c83388cd-34a3-5f9c-b19f-a46f9af3ccb9', '60000000-0000-0000-0000-000000000001', 'efa4a48c-e51d-5b8e-b8b4-3d3a20a9b24e', 'She is ______ engineer who works for a software company.', 'FILL_BLANK', NULL, NULL, NULL, '"engineer" bắt đầu bằng âm nguyên âm nên dùng "an".', 1, 4),
    ('da9bb4da-b004-5e6b-b613-a5b5215837b7', '60000000-0000-0000-0000-000000000001', 'efa4a48c-e51d-5b8e-b8b4-3d3a20a9b24e', 'The graph shows ______ increase in the number of tourists.', 'FILL_BLANK', NULL, NULL, NULL, '"increase" bắt đầu bằng nguyên âm nên dùng "an".', 1, 5),
    ('7975df95-13e2-554d-ba31-844e9e01d306', '60000000-0000-0000-0000-000000000001', 'efa4a48c-e51d-5b8e-b8b4-3d3a20a9b24e', 'Technology has changed ______ way we communicate.', 'FILL_BLANK', NULL, NULL, NULL, '"the way we communicate" chỉ một cách cụ thể nên dùng "the".', 1, 6),
    ('b10460e3-4be8-529a-906a-31ea00ff0bd7', '60000000-0000-0000-0000-000000000002', '469fc4fd-23c4-5124-b9b0-c0a508404853', 'The number of visitors ______ sharply between 2010 and 2020.', 'MULTIPLE_CHOICE', NULL, NULL, NULL, 'Mốc thời gian quá khứ xác định (2010-2020) dùng quá khứ đơn.', 1, 1),
    ('90d12ef2-cbf9-5811-b29c-61f0b5a61cfd', '60000000-0000-0000-0000-000000000002', '469fc4fd-23c4-5124-b9b0-c0a508404853', 'I ______ in Hanoi since 2015.', 'MULTIPLE_CHOICE', NULL, NULL, NULL, '"since 2015" đi với hiện tại hoàn thành.', 1, 2),
    ('4a5f0e26-84c2-5201-97d0-6103322f3676', '60000000-0000-0000-0000-000000000002', '469fc4fd-23c4-5124-b9b0-c0a508404853', 'If the government ______ more taxes, people would have less money.', 'MULTIPLE_CHOICE', NULL, NULL, NULL, 'Câu điều kiện loại 2: If + quá khứ đơn, would + động từ.', 1, 3),
    ('eb75f9cd-20cc-59ff-9063-cfddc2ccd7e3', '60000000-0000-0000-0000-000000000002', '469fc4fd-23c4-5124-b9b0-c0a508404853', 'Last year, I ______ IELTS for the first time.', 'MULTIPLE_CHOICE', NULL, NULL, NULL, '"Last year" là mốc quá khứ xác định nên dùng quá khứ đơn.', 1, 4),
    ('17554138-4e69-5aae-8e26-ba12a5eaca44', '60000000-0000-0000-0000-000000000002', '14df75a7-4b76-5d17-a5d7-7a1f2e700534', 'By the time the lecture started, most students ______ (arrive) already.', 'FILL_BLANK', NULL, NULL, NULL, 'Hành động xảy ra trước một mốc quá khứ dùng quá khứ hoàn thành.', 1, 5),
    ('e8d2f400-8cf1-5ba8-b649-8f8d175bd73f', '60000000-0000-0000-0000-000000000002', '14df75a7-4b76-5d17-a5d7-7a1f2e700534', 'Scientists predict that sea levels ______ (rise) further over the next 30 years.', 'FILL_BLANK', NULL, NULL, NULL, 'Dự đoán về tương lai dùng "will" hoặc "be going to".', 1, 6),
    ('e1935dd9-f3fc-51e9-9429-bd47e0fdebb9', '60000000-0000-0000-0000-000000000003', 'ad3710c0-5796-5214-98c6-cc2921621508', 'The number of students ______ increased.', 'MULTIPLE_CHOICE', NULL, NULL, NULL, '"The number of" đi với động từ số ít.', 1, 1),
    ('8bf4f94d-9562-5b0c-9953-618e38128a0e', '60000000-0000-0000-0000-000000000003', 'ad3710c0-5796-5214-98c6-cc2921621508', 'Each of the candidates ______ a separate room.', 'MULTIPLE_CHOICE', NULL, NULL, NULL, '"Each of" đi với động từ số ít.', 1, 2),
    ('e64ea6ce-123a-5375-9263-3eb66701d9df', '60000000-0000-0000-0000-000000000003', 'ad3710c0-5796-5214-98c6-cc2921621508', 'Neither the teacher nor the students ______ happy with the result.', 'MULTIPLE_CHOICE', NULL, NULL, NULL, 'Với "neither...nor", động từ hòa hợp với chủ ngữ gần nhất (students).', 1, 3),
    ('e2e01dbd-b9c1-5bef-88b3-6d4443e48ff0', '60000000-0000-0000-0000-000000000003', 'ad3710c0-5796-5214-98c6-cc2921621508', 'Information about universities ______ available online.', 'MULTIPLE_CHOICE', NULL, NULL, NULL, '"Information" là danh từ không đếm được nên dùng động từ số ít.', 1, 4),
    ('b6a6a829-90ea-5e43-832e-72a6a1ac799d', '60000000-0000-0000-0000-000000000003', '243bda4f-e678-56ff-ae53-1ed03aae2378', 'Many ______ (child) in rural areas do not have access to computers.', 'FILL_BLANK', NULL, NULL, NULL, 'Số nhiều bất quy tắc của "child" là "children".', 1, 5),
    ('cd16dbed-edcd-5559-9621-87d5883acd0f', '60000000-0000-0000-0000-000000000003', '243bda4f-e678-56ff-ae53-1ed03aae2378', 'There ______ (be) several reasons for this trend.', 'FILL_BLANK', NULL, NULL, NULL, '"several reasons" là số nhiều nên dùng "are".', 1, 6),
    ('45def4ee-b09d-597d-a0ed-44c86516cbd3', '60000000-0000-0000-0000-000000000004', '0ba380c5-36fd-5464-809a-f72ed882e0e7', 'Many students are interested ______ studying abroad.', 'MULTIPLE_CHOICE', NULL, NULL, NULL, '"interested in".', 1, 1),
    ('f156173e-7b1b-56f0-ae53-dde6d902a82b', '60000000-0000-0000-0000-000000000004', '0ba380c5-36fd-5464-809a-f72ed882e0e7', 'The graph shows a rise ______ unemployment.', 'MULTIPLE_CHOICE', NULL, NULL, NULL, '"a rise in + danh từ".', 1, 2),
    ('c3900dc1-881b-502a-bae7-109c683b48f0', '60000000-0000-0000-0000-000000000004', '0ba380c5-36fd-5464-809a-f72ed882e0e7', 'The population increased ______ 5 million to 8 million.', 'MULTIPLE_CHOICE', NULL, NULL, NULL, '"from ... to ..." diễn tả mức đầu và mức cuối.', 1, 3),
    ('430505bd-674a-5c30-acb4-de717cc32c99', '60000000-0000-0000-0000-000000000004', '0ba380c5-36fd-5464-809a-f72ed882e0e7', 'I depend ______ my parents for financial support.', 'MULTIPLE_CHOICE', NULL, NULL, NULL, '"depend on".', 1, 4),
    ('43e1dc13-6134-5dbe-8595-be9d4167d69b', '60000000-0000-0000-0000-000000000004', 'c2af4a9c-de30-5994-8850-44c1289c58b2', 'She is good ______ solving problems.', 'FILL_BLANK', NULL, NULL, NULL, '"good at + V-ing".', 1, 5),
    ('f2b6e77b-818d-580e-94c5-1820155263cd', '60000000-0000-0000-0000-000000000004', 'c2af4a9c-de30-5994-8850-44c1289c58b2', 'Smoking is harmful ______ health.', 'FILL_BLANK', NULL, NULL, NULL, '"harmful to".', 1, 6),
    ('41c1bf1f-e5da-5064-8ff2-6e1eda2c215e', '60000000-0000-0000-0000-000000000005', '224b0dd2-e8e4-5238-8c64-039f71957f48', 'Which sentence is correct?', 'MULTIPLE_CHOICE', NULL, NULL, NULL, 'Không dùng "but" hay "however" cùng với "although" trong một câu.', 1, 1),
