    ('c6e934c2-1568-54aa-9594-a3dba3a5373f', '60000000-0000-0000-0000-000000000016', 'ea8733cf-1723-5005-b6e9-7e93120569c3', 'Writing about a different subject from the question is called going off-______.', 'FILL_BLANK', NULL, NULL, NULL, '"off-topic" = lạc đề.', 1, 6),
