    ('186856a4-39df-5687-8048-3c2c97759a0a', '60000000-0000-0000-0000-000000000017', 'b22a2ceb-57fc-5a3c-a47b-93e7ac2cbfeb', 'Which paragraph is underdeveloped?', 'MULTIPLE_CHOICE', NULL, NULL, NULL, 'Đoạn đầu chỉ nêu ý, không giải thích hay dẫn chứng.', 1, 4),
