    ('3146c45a-44cf-56a9-986f-e848acbabc2f', '60000000-0000-0000-0000-000000000017', 'c48bca7b-6b9d-50b1-b7ce-f43bf353517b', 'To give an example, you can write "For ______" or "For instance".', 'FILL_BLANK', NULL, NULL, NULL, '"For example".', 1, 6),
