    ('95de5223-1a0b-5464-9fe7-652c65f77d12', '60000000-0000-0000-0000-000000000018', 'dad019f2-422c-5bd0-9670-466fe4d660e6', 'A 300-word essay written as a single block makes the essay:', 'MULTIPLE_CHOICE', NULL, NULL, NULL, 'Không chia đoạn khiến bài khó theo dõi.', 1, 5),
    ('0892be44-9e93-5b07-91d4-a02ef25c9f7b', '60000000-0000-0000-0000-000000000018', 'adf37929-8b34-5414-968f-6d58cd21becf', 'Each body paragraph usually starts with a topic ______.', 'FILL_BLANK', NULL, NULL, NULL, '"topic sentence" nêu ý chính của đoạn.', 1, 6),
